// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! `--dry-run`: the SDK builds the request as usual and hands it to an HTTP client that records
//! it instead of sending it, then fails the call; the run prints the request and exits 0.
//! Generated code plugs [`Recorder::record`] into the SDK's `HttpClient` trait.
use std::{
    future::Future,
    sync::{Arc, Mutex},
};

pub use hyper::body::Incoming;
use hyper::body::{Body, Buf};
use serde_json::{json, Map, Value};

pub type BoxError = Box<dyn std::error::Error + Send + Sync>;

/// The token commands get under `--dry-run`: no credential is needed, none is shown.
pub const TOKEN: &str = "<redacted>";

/// Headers whose values are secrets.
const SECRET_HEADERS: [&str; 4] = [
    "authorization",
    "proxy-authorization",
    "cookie",
    "x-api-key",
];

/// The first request of a dry run, shared with the SDK's client.
#[derive(Clone, Debug, Default)]
pub struct Recorder(Arc<Mutex<Option<Value>>>);

impl Recorder {
    /// Records `request` as `{"method", "url", "query", "headers", "body"}` and fails, so
    /// nothing is sent and no further request follows.
    pub fn record<B>(
        &self,
        request: hyper::Request<B>,
    ) -> impl Future<Output = Result<hyper::Response<Incoming>, BoxError>> + Send + Sync + 'static
    where
        B: Body + Send + Sync + 'static,
        B::Data: Send + Sync,
        B::Error: std::fmt::Display,
    {
        let slot = self.0.clone();
        async move {
            let (parts, body) = request.into_parts();
            let mut body = Box::pin(body);
            let mut bytes = Vec::new();
            while let Some(frame) = std::future::poll_fn(|cx| body.as_mut().poll_frame(cx)).await {
                let frame = frame.map_err(|error| format!("reading the request body: {error}"))?;
                if let Ok(mut data) = frame.into_data() {
                    while data.has_remaining() {
                        let chunk = data.chunk();
                        bytes.extend_from_slice(chunk);
                        let read = chunk.len();
                        data.advance(read);
                    }
                }
            }
            let described = describe(&parts, &bytes);
            let mut slot = slot.lock().unwrap_or_else(|e| e.into_inner());
            slot.get_or_insert(described);
            Err("--dry-run: the request was not sent".into())
        }
    }

    /// The recorded request, if the command got as far as sending one.
    pub fn take(&self) -> Option<Value> {
        self.0.lock().unwrap_or_else(|e| e.into_inner()).take()
    }
}

fn describe(parts: &hyper::http::request::Parts, body: &[u8]) -> Value {
    let uri = &parts.uri;
    let url = match (uri.scheme_str(), uri.authority()) {
        (Some(scheme), Some(authority)) => format!("{scheme}://{authority}{}", uri.path()),
        _ => uri.path().to_owned(),
    };
    let mut query = Map::new();
    for pair in uri
        .query()
        .unwrap_or_default()
        .split('&')
        .filter(|p| !p.is_empty())
    {
        let (key, value) = pair.split_once('=').unwrap_or((pair, ""));
        let (key, value) = (decode(key), Value::String(decode(value)));
        match query.get_mut(&key) {
            Some(Value::Array(values)) => values.push(value),
            Some(first) => *first = Value::Array(vec![first.take(), value]),
            None => {
                query.insert(key, value);
            }
        }
    }
    let mut headers = Map::new();
    for (name, value) in &parts.headers {
        let value = match SECRET_HEADERS.contains(&name.as_str()) {
            true => redact(value.to_str().unwrap_or_default()),
            false => String::from_utf8_lossy(value.as_bytes()).into_owned(),
        };
        headers.insert(name.as_str().to_owned(), Value::String(value));
    }
    let content_type = parts
        .headers
        .get("content-type")
        .and_then(|value| value.to_str().ok())
        .unwrap_or_default();
    let body = match std::str::from_utf8(body) {
        _ if body.is_empty() => Value::Null,
        Ok(text) if content_type.contains("json") => {
            serde_json::from_str(text).unwrap_or_else(|_| Value::String(text.to_owned()))
        }
        Ok(text) => Value::String(text.to_owned()),
        Err(_) => Value::String(format!("<{} bytes of binary data>", body.len())),
    };
    json!({
        "method": parts.method.as_str(),
        "url": url,
        "query": query,
        "headers": headers,
        "body": body,
    })
}

/// `Bearer <redacted>`: the scheme stays, the secret goes.
fn redact(value: &str) -> String {
    match value.split_once(' ') {
        Some((scheme, _)) => format!("{scheme} {TOKEN}"),
        None => TOKEN.to_owned(),
    }
}

fn decode(text: &str) -> String {
    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        let hex = bytes
            .get(i + 1..i + 3)
            .and_then(|hex| std::str::from_utf8(hex).ok())
            .and_then(|hex| u8::from_str_radix(hex, 16).ok());
        match (bytes[i], hex) {
            (b'%', Some(byte)) => {
                out.push(byte);
                i += 3;
            }
            (byte, _) => {
                out.push(byte);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[derive(Default)]
    struct Bytes(Option<Vec<u8>>);

    impl Body for Bytes {
        type Data = std::io::Cursor<Vec<u8>>;
        type Error = std::io::Error;

        fn poll_frame(
            mut self: std::pin::Pin<&mut Self>,
            _: &mut std::task::Context<'_>,
        ) -> std::task::Poll<Option<Result<hyper::body::Frame<Self::Data>, Self::Error>>> {
            let data = self
                .0
                .take()
                .map(|bytes| Ok(hyper::body::Frame::data(std::io::Cursor::new(bytes))));
            std::task::Poll::Ready(data)
        }
    }

    fn recorded(request: hyper::Request<Bytes>) -> Value {
        let recorder = Recorder::default();
        let runtime = tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap();
        let error = runtime.block_on(recorder.record(request)).unwrap_err();
        assert_eq!(error.to_string(), "--dry-run: the request was not sent");
        recorder.take().unwrap()
    }

    #[test]
    fn requests_are_described_with_secrets_redacted() {
        let request =
            hyper::Request::post("https://api.acme.dev/v1/things?status=a&status=b&q=x%20y")
                .header("authorization", "Bearer sk_live_123")
                .header("content-type", "application/json")
                .header("idempotency-key", "k1")
                .body(Bytes(Some(br#"{"name":"Lamp"}"#.to_vec())))
                .unwrap();
        assert_eq!(
            recorded(request),
            json!({
                "method": "POST",
                "url": "https://api.acme.dev/v1/things",
                "query": {"status": ["a", "b"], "q": "x y"},
                "headers": {"authorization": "Bearer <redacted>", "content-type": "application/json",
                            "idempotency-key": "k1"},
                "body": {"name": "Lamp"},
            })
        );
    }

    #[test]
    fn bodies_that_are_not_json_are_text_or_a_size() {
        let text = hyper::Request::put("/up")
            .body(Bytes(Some(b"plain".to_vec())))
            .unwrap();
        assert_eq!(recorded(text)["body"], json!("plain"));
        let binary = hyper::Request::put("/up")
            .body(Bytes(Some(vec![0xff, 0xfe])))
            .unwrap();
        assert_eq!(recorded(binary)["body"], json!("<2 bytes of binary data>"));
        let empty = hyper::Request::get("/x").body(Bytes::default()).unwrap();
        assert_eq!(recorded(empty)["body"], Value::Null);
    }
}
